pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let total_cents: i64 = input
        .as_array()
        .unwrap()
        .iter()
        .map(|item| {
            let array = item.as_array().unwrap();
            let unit_price_cents = array[0].as_i64().unwrap() as i64;
            let quantity = array[1].as_i64().unwrap() as i64;
            unit_price_cents * quantity
        })
        .sum();
    serde_json::Value::from(total_cents)
}
